sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    var ga = new GlideAjax('VendorRiskUtils');
    ga.addParam('sysparm_name', 'isDuplicateTaxId');
    ga.addParam('sysparm_tax_id', newValue);
    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            g_form.setValue('tax_id', '');
            g_form.showFieldMsg('tax_id', 'A Vendor Request with that Tax ID already exists!', 'error');
        }
    });
}
